// Some portions generated by Claude
import { AdaptiveBatchLoader } from "./request-batching.ts";
import { anchors, scoped, type GraphScope } from "./rdf-vocabulary.ts";
import { isSafeSparqlIri } from "./rdf-terms.ts";
import type { RdfBinding, RdfQuery } from "./rdf-explorer.ts";
export function connectionQuery(ids: string[], scope: GraphScope = "default") {
  return `SELECT DISTINCT ?source ?predicate ?target WHERE { ${anchors(ids, "source")} ${scoped("?source ?predicate ?target . FILTER(isIRI(?target))", scope)} } LIMIT 4096`;
}
/** Scan bound sources once, then intersect results locally; no quadratic source × target query matrix. */
export async function discoverConnections(
  ids: string[],
  query: RdfQuery,
  scope: GraphScope,
  signal: AbortSignal,
  onProgress?: (requests: number) => void,
) {
  const loaded = new Set(ids.filter(isSafeSparqlIri)),
    truncated = new Set<string>();
  let requests = 0;
  const loader = new AdaptiveBatchLoader<RdfBinding[]>(
    async (keys, abort) => {
      requests++;
      onProgress?.(requests);
      const rows =
        (await query(connectionQuery(keys, scope), abort)).results?.bindings ??
        [];
      const values = new Map(keys.map((key) => [key, [] as RdfBinding[]]));
      for (const row of rows)
        if (
          row.source?.type === "uri" &&
          row.target?.type === "uri" &&
          loaded.has(row.target.value)
        )
          values.get(row.source.value)?.push(row);
      if (rows.length >= 4096 && keys.length === 1) truncated.add(keys[0]);
      return { values, rows: rows.length, saturated: rows.length >= 4096 };
    },
    { initialSize: 32, maximumSize: 128 },
  );
  try {
    const rows = await loader.loadMany([...loaded], signal);
    return {
      bindings: rows.flatMap(([, value]) => value ?? []),
      requests,
      truncatedSources: truncated.size,
    };
  } finally {
    loader.dispose();
  }
}
